// Matriks 3x3 disimpan sebagai array 9 angka, baris demi baris.
function kaliMatriks(a, b) {
  const hasil = [];
  for (let r = 0; r < 3; r++) {
    for (let c = 0; c < 3; c++) {
      hasil.push(a[r * 3] * b[c] + a[r * 3 + 1] * b[3 + c] + a[r * 3 + 2] * b[6 + c]);
    }
  }
  return hasil;
}

