const id = ([r, k]) => r + ',' + k;

const g = { [id(awal)]: 0 };
const asal = {};
const tertutup = new Set();
let terbuka = [{ sel: awal, f: h(awal), h: h(awal), urut: 0 }];
let urut = 1;
let ketemu = false;

while (terbuka.length > 0) {
  // f terkecil, lalu h terkecil, lalu yang lebih dulu masuk.
  terbuka.sort((a, b) => a.f - b.f || a.h - b.h || a.urut - b.urut);
  const { sel } = terbuka.shift();
  if (tertutup.has(id(sel))) continue;
  tertutup.add(id(sel));
  if (id(sel) === id(tujuan)) { ketemu = true; break; }
  for (const [dr, dk] of ARAH) {
    const t = [sel[0] + dr, sel[1] + dk];
    const ch = peta[t[0]] ? peta[t[0]][t[1]] : undefined;
    if (ch === undefined || ch === '#' || tertutup.has(id(t))) continue;
    const gBaru = g[id(sel)] + biaya(ch);
