function tepi(a, b, p) {
  return (b.x - a.x) * (p.y - a.y) - (b.y - a.y) * (p.x - a.x);
}

function atasKiri(a, b) {
  const dx = b.x - a.x;
  const dy = b.y - a.y;
  return (dy === 0 && dx > 0) || dy < 0;
}

function masuk(w, a, b) {
  return w > 0 || (w === 0 && atasKiri(a, b));
}

