const [lebar, tinggi, fov] = baris[1].trim().split(/\s+/).map(Number);

const DEKAT = 0.1;
const r = (yaw * Math.PI) / 180;
const f = 1 / Math.tan((fov * Math.PI) / 360);
const aspek = lebar / tinggi;

baris.slice(2).forEach((teks, i) => {
  const [x, y, z] = teks.trim().split(/\s+/).map(Number);
  // view transform: geser dunia supaya kamera di titik nol, lalu putar balik
  const dx = x - cx;
  const dy = y - cy;
  const dz = z - cz;
  const vx = dx * Math.cos(r) - dz * Math.sin(r);
  const vy = dy;
  const vz = dx * Math.sin(r) + dz * Math.cos(r);
  const label = `titik ${i + 1}:`;
  if (vz > -DEKAT) {
    console.log(`${label} di belakang kamera`);
    return;
  }
  // proyeksi perspektif: bagi dengan jarak (-vz)
  const ndcX = ((f / aspek) * vx) / -vz;
  const ndcY = (f * vy) / -vz;
  const px = Math.floor(((ndcX + 1) / 2) * lebar);
  const py = Math.floor(((1 - ndcY) / 2) * tinggi);
  if (px < 0 || px >= lebar || py < 0 || py >= tinggi) {
    console.log(`${label} di luar layar`);
    return;
  }
  console.log(`${label} (${px}, ${py}) kedalaman ${(-vz).toFixed(2)}`);
});

