const baris = require('fs').readFileSync(0, 'utf8').trim().split('\n').map((b) => b.trim().split(/\s+/));

let LANGKAH = 20;
let LEBAR = 0;
let TINGGI = 0;
const awal = [];
const frame = [];
for (const k of baris) {
  if (k[0] === 'langkah') LANGKAH = Number(k[1]);
  else if (k[0] === 'arena') [LEBAR, TINGGI] = [Number(k[1]), Number(k[2])];
  else if (k[0] === 'entitas') awal.push(k.slice(1));
  else if (k[0] === 'frame') frame.push({ ms: Number(k[1]), input: k[2] });
}

const ARAH = { kanan: [2, 0], kiri: [-2, 0], atas: [0, -2], bawah: [0, 2], diam: [0, 0] };

// Dunia ECS: satu Map per jenis komponen, dikunci nomor entitas.
function buatDunia() {
  const d = {
    nama: new Map(), jenis: new Map(), posisi: new Map(),
    kotak: new Map(), kecepatan: new Map(), nyawa: new Map(),
    skor: 0, tick: 0, selesai: false,
  };
  awal.forEach(([nama, jenis, x, y, w, h, vx, vy], i) => {
    const id = i + 1;
    d.nama.set(id, nama);
    d.jenis.set(id, jenis);
    d.posisi.set(id, { x: Number(x), y: Number(y) });
    d.kotak.set(id, { w: Number(w), h: Number(h) });
    d.kecepatan.set(id, { x: Number(vx), y: Number(vy) });
    if (jenis === 'pemain') d.nyawa.set(id, 3);
  });
  return d;
}

function ids(peta) {
  return [...peta.keys()].sort((a, b) => a - b);
}

function hancurkan(d, id) {
  for (const p of [d.nama, d.jenis, d.posisi, d.kotak, d.kecepatan, d.nyawa]) p.delete(id);
}

function sistemInput(d, input) {
  for (const id of ids(d.jenis)) {
    if (d.jenis.get(id) !== 'pemain') continue;
    const [vx, vy] = ARAH[input] || ARAH.diam;
    d.kecepatan.set(id, { x: vx, y: vy });
  }
}

function sistemGerak(d) {
  for (const id of ids(d.kecepatan)) {
    const p = d.posisi.get(id);
    const v = d.kecepatan.get(id);
    p.x += v.x;
    p.y += v.y;
  }
}

function sistemArena(d) {
  for (const id of ids(d.posisi)) {
    const p = d.posisi.get(id);
    const k = d.kotak.get(id);
    const v = d.kecepatan.get(id);
    const maksX = LEBAR - k.w;
    const maksY = TINGGI - k.h;
    if (p.x < 0 || p.x > maksX) {
      p.x = Math.min(Math.max(p.x, 0), maksX);
      if (d.jenis.get(id) === 'musuh') v.x = -v.x;
    }
    if (p.y < 0 || p.y > maksY) {
      p.y = Math.min(Math.max(p.y, 0), maksY);
      if (d.jenis.get(id) === 'musuh') v.y = -v.y;
    }
  }
}

function tabrak(a, ka, b, kb) {
  return a.x < b.x + kb.w && b.x < a.x + ka.w && a.y < b.y + kb.h && b.y < a.y + ka.h;
}

function sistemTabrakan(d, cetak) {
  const pemain = ids(d.jenis).find((id) => d.jenis.get(id) === 'pemain');
  if (pemain === undefined) return;
  for (const id of ids(d.posisi)) {
    if (id === pemain || !d.posisi.has(pemain)) continue;
    if (!tabrak(d.posisi.get(pemain), d.kotak.get(pemain), d.posisi.get(id), d.kotak.get(id))) continue;
    const nama = d.nama.get(id);
    if (d.jenis.get(id) === 'koin') {
      d.skor += 10;
      hancurkan(d, id);
      cetak(`ambil ${nama} (skor ${d.skor})`);
    } else if (d.jenis.get(id) === 'musuh') {
      const sisa = d.nyawa.get(pemain) - 1;
      d.nyawa.set(pemain, sisa);
      hancurkan(d, id);
      cetak(`kena ${nama} (nyawa ${sisa})`);
      if (sisa <= 0) {
        hancurkan(d, pemain);
        cetak('pemain kalah');
        d.selesai = true;
        return;
      }
    }
  }
  const sisaKoin = ids(d.jenis).filter((id) => d.jenis.get(id) === 'koin').length;
  if (sisaKoin === 0) {
    cetak('semua koin terambil');
    d.selesai = true;
  }
}

function satuTick(d, input, cetak) {
  d.tick++;
  sistemInput(d, input);
  sistemGerak(d);
  sistemArena(d);
  sistemTabrakan(d, (teks) => cetak(`tick ${d.tick}: ${teks}`));
}

function checksum(d) {
  const M = 1000003;
  let h = 0;
  const tambah = (v) => { h = (((h * 31 + v) % M) + M) % M; };
  for (const id of ids(d.posisi)) {
    const p = d.posisi.get(id);
    tambah(id);
    tambah(p.x);
    tambah(p.y);
  }
  const nyawa = [...d.nyawa.values()][0] || 0;
  tambah(d.tick);
  tambah(d.skor);
  tambah(nyawa);
  return h;
}

// Main pertama: frame -> akumulator -> tick, sambil merekam input per tick.
const dunia = buatDunia();
const rekaman = [];
let akumulator = 0;
for (const f of frame) {
  if (dunia.selesai) break;
  akumulator += f.ms;
  while (akumulator >= LANGKAH && !dunia.selesai) {
    akumulator -= LANGKAH;
    rekaman.push(f.input);
    satuTick(dunia, f.input, (teks) => console.log(teks));
  }
}
const nyawaAkhir = [...dunia.nyawa.values()][0] || 0;
console.log(`akhir tick ${dunia.tick}: skor ${dunia.skor}, nyawa ${nyawaAkhir}`);
for (const id of ids(dunia.posisi)) {
  const p = dunia.posisi.get(id);
  console.log(`  ${dunia.nama.get(id)} (${p.x},${p.y})`);
}
const c1 = checksum(dunia);
console.log(`checksum ${c1}`);

// Replay: dunia baru dari keadaan awal, input diambil dari rekaman saja.
const ulang = buatDunia();
for (const input of rekaman) satuTick(ulang, input, () => {});
const c2 = checksum(ulang);
console.log(`replay ${rekaman.length} tick: checksum ${c2}`);
console.log(c1 === c2 ? 'replay cocok' : 'replay beda');
